edges_flat = [0, 1, 0, 2, 0, 3, 0, 6, 1, 3, 1, 4, 1, 6, 2, 4, 2, 5, 2, 6, 2, 11, 2, 13, 3, 4, 3, 5, 3, 6, 3, 10, 4, 5, 4, 6, 4, 12, 5, 6, 7, 8, 7, 9, 7, 10, 7, 11, 7, 12, 7, 13, 8, 9, 8, 10, 8, 11, 8, 12, 8, 13, 9, 10, 9, 11, 9, 13, 11, 12]
edges = [(edges_flat[i], edges_flat[i+1]) for i in range(0, len(edges_flat), 2)]

n = 14
adj = [[] for _ in range(n)]
for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

def is_bipartite():
    color = [-1] * n
    for i in range(n):
        if color[i] == -1:
            q = [i]
            color[i] = 0
            while q:
                u = q.pop(0)
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        q.append(v)
                    elif color[v] == color[u]:
                        return False
    return True

print("Is bipartite:", is_bipartite())

def can_color(k):
    color = [-1] * n
    def solve(u):
        if u == n:
            return True
        for c in range(k):
            ok = True
            for v in adj[u]:
                if color[v] == c:
                    ok = False
                    break
            if ok:
                color[u] = c
                if solve(u + 1):
                    return True
                color[u] = -1
        return False
    return solve(0)

for k in range(1, 6):
    if can_color(k):
        print("Chromatic number:", k)
        break
